#include <iostream>
#include <vector>
#include <algorithm>
#include <queue>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<long long> t(n);
    for (int i = 0; i < n; ++i) {
        cin >> t[i];
    }

    vector<long long> f(m);
    for (int j = 0; j < m; ++j) {
        cin >> f[j];
    }

    // Ordenar os mecânicos e considerar no máximo os min(n, m) mais rápidos
    sort(f.begin(), f.end());
    int k = min(n, m);

    // Min-heap de pares: {custo_atual, indice_do_mecanico}
    // Para evitar recalcular coeficientes, guardamos {custo, j}
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;
    for (int j = 0; j < k; ++j) {
        pq.push({0LL, j});
    }

    vector<long long> slot_costs(n);
    for (int i = 0; i < n; ++i) {
        auto [cost, j] = pq.top();
        pq.pop();
        slot_costs[i] = cost;
        pq.push({cost + f[j], j});
    }

    // Ordenar tempos base dos carros em ordem decrescente
    sort(t.begin(), t.end(), greater<long long>());

    // Calcular a soma mínima dos tempos de espera
    long long total_wait_time = 0;
    for (int i = 0; i < n; ++i) {
        total_wait_time += t[i] * slot_costs[i];
    }

    cout << total_wait_time << "\n";

    return 0;
}
